      const size = 0.85 - i * 0.05;
      const grp = new Group();
      const body = new Mesh(new SphereGeometry(size, 8, 6), scaleMat);
      body.scale.set(1, 0.85, 1);
      grp.add(body);
      const band = new Mesh(new TorusGeometry(size * 0.85, 0.06, 6, 10), glowMat);
      band.rotation.x = Math.PI / 2;
      grp.add(band);
