  function addGrassBasePlane(def, group) {
    const geom = new PlaneGeometry(ROOM_W * TILE + 2, ROOM_H * TILE + 2);
    let baseColor = COLORS.grassDark;
    switch (def.biome) {
      case "snow":
        baseColor = 14280430;
        break;
      // pale blue-white
      case "wetland":
        baseColor = 4020794;
        break;
      // murky green
      case "meadow":
        baseColor = 10204252;
        break;
      // sun-lit yellow-green
      case "pine":
        baseColor = 3099189;
        break;
    }
    const mat = new MeshLambertMaterial({ color: baseColor });
    const mesh = new Mesh(geom, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.receiveShadow = true;
    mesh.position.y = -0.05;
    const c00 = tileCenter(def.gx, def.gy, 0, 0);
    mesh.position.x = c00.x + ROOM_W * TILE / 2 - TILE / 2;
    mesh.position.z = c00.z + ROOM_H * TILE / 2 - TILE / 2;
    group.add(mesh);
  }
