  // src/ui/minimap.ts
  var CELL = 22;
  var GAP = 3;
  var Minimap = class {
    constructor(mount) {
      let minGx = Infinity, minGy = Infinity, maxGx = -Infinity, maxGy = -Infinity;
      for (const r of ROOMS) {
        minGx = Math.min(minGx, r.gx);
        maxGx = Math.max(maxGx, r.gx);
        minGy = Math.min(minGy, r.gy);
        maxGy = Math.max(maxGy, r.gy);
      }
      this.minGx = minGx;
      this.minGy = minGy;
      this.cols = maxGx - minGx + 1;
      this.rows = maxGy - minGy + 1;
      this.canvas = document.createElement("canvas");
      this.canvas.width = this.cols * (CELL + GAP) + GAP;
      this.canvas.height = this.rows * (CELL + GAP) + GAP;
      this.canvas.id = "minimap";
      mount.appendChild(this.canvas);
      this.ctx = this.canvas.getContext("2d");
    }
    render(rooms, currentKey, time) {
      const ctx2 = this.ctx;
      ctx2.clearRect(0, 0, this.canvas.width, this.canvas.height);
      ctx2.fillStyle = "rgba(20, 12, 30, 0.75)";
      ctx2.fillRect(0, 0, this.canvas.width, this.canvas.height);
      for (const r of ROOMS) {
        const rt = rooms.get(r.key);
        if (!rt) continue;
        const x = GAP + (r.gx - this.minGx) * (CELL + GAP);
        const y = GAP + (r.gy - this.minGy) * (CELL + GAP);
        if (!rt.visited) {
          ctx2.fillStyle = "rgba(255,255,255,0.05)";
          ctx2.fillRect(x, y, CELL, CELL);
          continue;
        }
        let color2 = "#5a4880";
        if (r.biome === "village") color2 = "#5a8a48";
        if (r.key === "0,0") color2 = "#8a3a4c";
        ctx2.fillStyle = color2;
        ctx2.fillRect(x, y, CELL, CELL);
        if (r.key === currentKey) {
          const p = 0.5 + 0.5 * Math.sin(time * 5);
          ctx2.strokeStyle = `rgba(255,255,255,${0.4 + 0.5 * p})`;
          ctx2.lineWidth = 2;
          ctx2.strokeRect(x + 1, y + 1, CELL - 2, CELL - 2);
        } else {
          ctx2.strokeStyle = "rgba(0,0,0,0.6)";
          ctx2.lineWidth = 1;
          ctx2.strokeRect(x + 0.5, y + 0.5, CELL - 1, CELL - 1);
        }
        for (const d of rt.doors) {
          ctx2.fillStyle = d.gateClosed ? "#dd4422" : "#eae0c9";
          if (d.dir === "n") ctx2.fillRect(x + CELL / 2 - 2, y - 1, 4, 3);
          if (d.dir === "s") ctx2.fillRect(x + CELL / 2 - 2, y + CELL - 2, 4, 3);
          if (d.dir === "w") ctx2.fillRect(x - 1, y + CELL / 2 - 2, 3, 4);
          if (d.dir === "e") ctx2.fillRect(x + CELL - 2, y + CELL / 2 - 2, 3, 4);
        }
      }
    }
    markVisited(_key) {
    }
  };

